package kr.workbench;
import javax.swing.*;import javax.swing.table.*;import java.util.*;
public class DisplayWorkflowTest extends WorkbenchTest {
 public static void main(String[] args)throws Exception{
 edt(()->{EnvironmentPanel p=new EnvironmentPanel(null);var site=p.catalog.observe("https://test/","Server: nginx\nContent-Type: application/vnd.spring-boot.actuator.v3+json","<script src='/swagger-ui/main.js'></script>");p.origins.addItem(site.origin);int full=p.candidates.size();check(full>20,"all categories and common paths initially shown");
 ((TableRowSorter<?>)p.technologies.getRowSorter()).setSortKeys(List.of(new RowSorter.SortKey(0,SortOrder.DESCENDING)));int server=-1;for(int row=0;row<p.technologies.getRowCount();row++)if(p.technologies.getValueAt(row,0).equals("서버"))server=row;p.technologies.setRowSelectionInterval(server,server);
 check(p.category.equals("서버")&&p.candidates.stream().allMatch(c->c.source().startsWith("nginx")),"sorted category click filters nginx candidates and excludes other technologies");check(p.candidates.size()<full,"category filter reduces candidates");p.refresh();check(p.category.equals("서버")&&p.technologies.getSelectedRow()>=0,"passive refresh preserves selected category");p.category=null;p.refresh();check(p.candidates.size()==full,"all environments restores full candidate list");p.close();});
 String raw="HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n{\"id\":9007199254740993,\"s\":\"a,}\\\"b\",\"items\":[{\"x\":1},true,null],\"empty\":{}}";String formatted=PacketFormat.pretty(raw);check(formatted.startsWith("HTTP/1.1 200 OK\r\nContent-Type: application/json"),"formatter retains headers");check(formatted.contains("\n  \"id\": 9007199254740993"),"JSON indents without rounding large integer");check(formatted.contains("a,}\\\"b"),"JSON string escaping preserved");check(raw.contains("\r\n\r\n{\"id\""),"original raw packet remains unchanged");
 String xml=PacketFormat.pretty("HTTP/1.1 200\r\n\r\n<root><child>hello</child></root>");check(xml.contains("\n  <child>"),"XML pretty indentation");String xxe="HTTP/1.1 200\r\n\r\n<!DOCTYPE r [<!ENTITY e SYSTEM 'file:///etc/passwd'>]><r>&e;</r>";check(PacketFormat.pretty(xxe).equals(xxe),"XML external entity document stays raw without resolving entity");String invalid="HTTP/1.1 200\r\n\r\n{invalid}";check(PacketFormat.pretty(invalid).equals(invalid),"malformed JSON remains raw");String html=PacketFormat.pretty("HTTP/1.1 200\r\n\r\n<html><body><p>hello</p></body></html>");check(html.contains("\n<body>"),"HTML tag boundaries become readable lines");System.out.println("DisplayWorkflowTest: "+checks+" checks passed");
 }
}
